export type AgentIntentEvalCase = {
  id: string;
  surface: "dashboard" | "storefront";
  kind: "read" | "write" | "mixed";
  prompt: string;
  expectedOperationIds: string[];
  forbiddenOperationIds?: string[];
  expectedDisposition?: "execute" | "ask" | "unsupported" | "refuse";
  safetyAssertions?: string[];
  requiresFacts?: boolean;
  requiresConfirmation?: boolean;
  requiresVerification?: boolean;
};

